/**
 * Errors surfaced by the API client. An ApiError carries only machine-readable data: the HTTP
 * status, a stable problem `code` and the correlation ID. It never carries the server's `title`
 * or `detail`, which may echo request content, so the UI cannot display raw server text by accident.
 */

/** Stable RFC 9457 problem codes are lower snake case (OpenAPI Problem.code pattern). */
export const PROBLEM_CODE_PATTERN = /^[a-z][a-z0-9_]{0,63}$/;
/** Correlation IDs echoed or generated by the control plane (X-Request-ID format). */
export const REQUEST_ID_PATTERN = /^[A-Za-z0-9_.:-]{8,128}$/;

/** Codes produced on the client side (no usable server problem document). */
export type ClientErrorCode = 'network_error' | 'timeout' | 'invalid_response' | 'unknown';

export class ApiError extends Error {
  /** HTTP status, or 0 when no response was received. */
  readonly status: number;
  /** Stable problem code from the server, or a ClientErrorCode. */
  readonly code: string;
  /** Validated correlation ID for support requests, if any. */
  readonly requestId: string | null;

  constructor(status: number, code: string, requestId: string | null = null) {
    const safeCode = PROBLEM_CODE_PATTERN.test(code) ? code : 'unknown';
    super(`API request failed (${status === 0 ? 'no response' : `HTTP ${status}`}, ${safeCode})`);
    this.name = 'ApiError';
    this.status = status;
    this.code = safeCode;
    this.requestId = requestId !== null && REQUEST_ID_PATTERN.test(requestId) ? requestId : null;
  }
}

export function isApiError(error: unknown): error is ApiError {
  return error instanceof ApiError;
}

export function isAbortError(error: unknown): boolean {
  return (
    typeof error === 'object' &&
    error !== null &&
    'name' in error &&
    (error as { name?: unknown }).name === 'AbortError'
  );
}

/** Normalises anything thrown into an ApiError without keeping its message. */
export function toApiError(error: unknown): ApiError {
  if (isApiError(error)) return error;
  return new ApiError(0, 'unknown');
}

/** True when the candidate session is gone (expired, revoked by a newer exchange, or another interview). */
export function isSessionLost(error: ApiError): boolean {
  return error.status === 401 || error.status === 404 || error.code === 'unauthorized';
}
